actions.script:
def terminalDenied = false
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!ec.user.isInGroup('ADMIN')) {
    ec.user.context.activeOrgId = null
    ec.user.context.userOrgIds = []
    ec.user.context.filterOrgIds = []
    def partyId = ec.user.userAccount?.partyId
    def info = partyId ? ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo')
            .parameters([partyId:partyId]).disableAuthz().call() : null
    def ids = info?.userOrgIds ?: []
    org = info?.activeOrgId
    if (!ids.contains(org)) org = null
    ec.user.context.activeOrgId = org
    ec.user.context.userOrgIds = ids
    ec.user.context.filterOrgIds = org ? [org] : []
}
organizationPartyId = org && org != '_NA_' ? org : null
allowed = organizationPartyId != null
// Only ownership probes bypass filters. Business reads/writes retain normal authorization.
def targets = [
    [transactionId,'zenith.erp.pos.PosTransaction','transactionId'],
    [sessionId,'zenith.erp.pos.PosSession','sessionId'],
    [terminalId,'zenith.erp.pos.PosTerminal','terminalId'],
    [templateId,'zenith.erp.pos.PosReceiptTemplate','templateId'],
    [cashEntryId,'zenith.erp.pos.PosCashEntry','cashEntryId'],
    [expenseId,'zenith.erp.pos.PosExpense','expenseId'],
    [wastageId,'zenith.erp.pos.PosStockWastage','wastageId'],
    [printerId,'zenith.erp.pos.PrinterConfiguration','printerId'],
    [kotId,'zenith.erp.pos.KitchenOrderTicket','kotId'],
    [waiterId,'zenith.erp.pos.Waiter','waiterId'],
    [qrPaymentId,'zenith.erp.pos.PosQrPayment','qrPaymentId']]
for (t in targets) {
    if (!t[0] || !allowed) continue
    def row = ec.entity.find(t[1]).condition(t[2],t[0]).disableAuthz().one()
    allowed = row != null && row.organizationPartyId == organizationPartyId
}
terminalRestricted = !ec.user.isInGroup('ADMIN') && !ec.user.isInGroup('ZENITH_ADMIN')
allowedTerminalIds = null
if (terminalRestricted && allowed) {
    def assignment = ec.entity.find('zenith.erp.pos.PosTerminalAssignment')
        .condition('organizationPartyId',organizationPartyId).condition('userId',ec.user.userId).disableAuthz().one()
    def assigned = assignment ? ec.entity.find('zenith.erp.pos.PosTerminal')
        .condition('terminalId',assignment.terminalId).condition('organizationPartyId',organizationPartyId)
        .condition('isActive','Y').disableAuthz().one() : null
    allowedTerminalIds = assigned ? [assigned.terminalId] : []
    def sessions = []
    if (sessionId) sessions.add(sessionId)
    if (transactionId) sessions.add(ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).disableAuthz().one()?.sessionId)
    if (heldId) sessions.add(ec.entity.find('zenith.erp.pos.PosHeldTransaction').condition('heldId',heldId).disableAuthz().one()?.sessionId)
    if (returnId) sessions.add(ec.entity.find('zenith.erp.pos.PosReturn').condition('returnId',returnId).disableAuthz().one()?.sessionId)
    if (terminalId && !allowedTerminalIds.contains(terminalId)) { allowed = false; terminalDenied = true }
    for (sid in sessions) {
        def s = sid ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sid)
            .condition('organizationPartyId',organizationPartyId).disableAuthz().one() : null
        if (!s || !allowedTerminalIds.contains(s.terminalId) || s.operatorPartyId != ec.user.userAccount?.partyId) { allowed = false; terminalDenied = true }
    }
}
// Bill-login history, JSON reprints and direct receipt PDFs share this ownership check.
if (transactionId && allowed && !ec.user.isInGroup('ADMIN') && !ec.user.isInGroup('ZENITH_ADMIN') && !ec.user.isInGroup('ZENITH_STORE_MGR')) {
    def bill = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).disableAuthz().one()
    if (bill?.statusId == 'PtCompleted') {
        def billSession = ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',bill.sessionId)
            .condition('organizationPartyId',organizationPartyId).disableAuthz().one()
        allowed = billSession?.operatorPartyId == ec.user.userAccount?.partyId
    }
}
if (returnId && allowed) {
    def ret=ec.entity.find('zenith.erp.pos.PosReturn').condition('returnId',returnId).disableAuthz().one()
    def session=ret ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',ret.sessionId).disableAuthz().one() : null
    allowed=session!=null && session.organizationPartyId==organizationPartyId
}
if (heldId && allowed) {
    def held = ec.entity.find('zenith.erp.pos.PosHeldTransaction').condition('heldId',heldId).disableAuthz().one()
    def session = held ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',held.sessionId).disableAuthz().one() : null
    allowed = session != null && session.organizationPartyId == organizationPartyId
}
if (productId && allowed) {
    def product = ec.entity.find('mantle.product.Product').condition('productId',productId).disableAuthz().one()
    allowed = product != null && product.ownerPartyId == organizationPartyId
}
if (facilityId && allowed) {
    def facility=ec.entity.find('mantle.facility.Facility').condition('facilityId',facilityId).disableAuthz().one()
    allowed=facility!=null && facility.ownerPartyId==organizationPartyId
}
if (customerPartyId && allowed) {
    def customer = ec.entity.find('mantle.party.Party').condition('partyId',customerPartyId).disableAuthz().one()
    allowed = customer != null && customer.ownerPartyId == organizationPartyId
}
if (!allowed) ec.message.addError(terminalDenied ? 'Use the active terminal assigned to this login by your administrator.' : 'Select an authorized organization and a POS record belonging to it.')

if (!ec.user.isInGroup('ADMIN') && !ec.user.isInGroup('ZENITH_ADMIN')) {
    ec.message.addError('Only an administrator can assign billing terminals.'); return
}
def access=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
if (!access?.allowed) return
def org=access.organizationPartyId
def user=ec.entity.find('moqui.security.UserAccount').condition('userId',userId).disableAuthz().one()
def membership=user?.partyId ? ec.entity.find('mantle.party.PartyRelationship')
    .condition('fromPartyId',user.partyId).condition('toPartyId',org).condition('toRoleTypeId','OrgInternal')
    .conditionDate('fromDate','thruDate',ec.user.nowTimestamp).disableAuthz().one() : null
if (!membership || user.disabled=='Y') { ec.message.addError('Choose an active user in this organization.');return }
def terminal=terminalId ? ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId)
    .condition('organizationPartyId',org).condition('isActive','Y').one() : null
if (terminalId && !terminal?.facilityId) { ec.message.addError('Choose an active terminal assigned to a shop in this organization.');return }
if (terminal && !ec.entity.find('mantle.facility.Facility').condition('facilityId',terminal.facilityId).condition('ownerPartyId',org).one()) {
    ec.message.addError('The terminal shop must belong to this organization.');return
}
// Lock the user row so two assignment changes cannot race each other.
ec.entity.find('moqui.security.UserAccount').condition('userId',userId).forUpdate(true).disableAuthz().one()
def existing=ec.entity.find('zenith.erp.pos.PosTerminalAssignment').condition('organizationPartyId',org).condition('userId',userId).one()
if (existing?.terminalId==terminalId) return
if (ec.entity.find('zenith.erp.pos.PosSession').condition('organizationPartyId',org)
    .condition('operatorPartyId',user.partyId).condition('statusId','PsOpen').count()) {
    ec.message.addError('Close this user’s open sessions before changing their terminal assignment.');return
}
if (terminal) ec.entity.makeValue('zenith.erp.pos.PosTerminalAssignment')
    .setAll([organizationPartyId:org,userId:userId,terminalId:terminalId]).createOrUpdate()
else if (existing) existing.delete()
